120:     /**
121:      * Nodes are propagated in layers.
122:      * See {@link PropagationQueue} and {@link AbstractNode} for details.
123:      * This method determines the layer of each node.
124:      * It does so by reverse-engineering the parent nodes of each node.
125:      * Nodes without parents (forEach nodes) are in layer 0.
126:      * Nodes with parents are one layer above their parents.
127:      * Some nodes have multiple parents, such as {@link AbstractJoinNode} and {@link AbstractIfExistsNode}.
128:      * These are one layer above the highest parent.
129:      * This is done to ensure that, when a child node starts propagating, all its parents have already propagated.
130:      *
131:      * @param node never null
132:      * @param buildHelper never null
133:      * @return at least 0
134:      */
135:     private long determineLayerIndex(AbstractNode node, NodeBuildHelper<Score_> buildHelper) {
136:         if (node instanceof AbstractForEachUniNode<?>) { // ForEach nodes, and only they, are in layer 0.
137:             return 0;
138:         } else if (node instanceof AbstractJoinNode<?, ?, ?> joinNode) {
139:             var nodeCreator = (BavetJoinConstraintStream<?>) buildHelper.getNodeCreatingStream(joinNode);
140:             var leftParent = nodeCreator.getLeftParent();
141:             var rightParent = nodeCreator.getRightParent();
142:             var leftParentNode = buildHelper.findParentNode(leftParent);
143:             var rightParentNode = buildHelper.findParentNode(rightParent);
144:             return Math.max(leftParentNode.getLayerIndex(), rightParentNode.getLayerIndex()) + 1;
145:         } else if (node instanceof AbstractConcatNode<?> concatNode) {
146:             var nodeCreator = (BavetConcatConstraintStream<?>) buildHelper.getNodeCreatingStream(concatNode);
147:             var leftParent = nodeCreator.getLeftParent();
148:             var rightParent = nodeCreator.getRightParent();
149:             var leftParentNode = buildHelper.findParentNode(leftParent);
150:             var rightParentNode = buildHelper.findParentNode(rightParent);
151:             return Math.max(leftParentNode.getLayerIndex(), rightParentNode.getLayerIndex()) + 1;
152:         } else if (node instanceof AbstractIfExistsNode<?, ?> ifExistsNode) {
153:             var nodeCreator = (BavetIfExistsConstraintStream<?>) buildHelper.getNodeCreatingStream(ifExistsNode);
154:             var leftParent = nodeCreator.getLeftParent();
155:             var rightParent = nodeCreator.getRightParent();
156:             var leftParentNode = buildHelper.findParentNode(leftParent);
157:             var rightParentNode = buildHelper.findParentNode(rightParent);
158:             return Math.max(leftParentNode.getLayerIndex(), rightParentNode.getLayerIndex()) + 1;
159:         } else {
160:             var nodeCreator = (BavetAbstractConstraintStream<?>) buildHelper.getNodeCreatingStream(node);
161:             var parentNode = buildHelper.findParentNode(nodeCreator.getParent());
162:             return parentNode.getLayerIndex() + 1;
163:         }
