22: public final class NodeBuildHelper<Score_ extends Score<Score_>> {
23: 
24:     private final Set<? extends ConstraintStream> activeStreamSet;
25:     private final AbstractScoreInliner<Score_> scoreInliner;
26:     private final Map<AbstractNode, BavetAbstractConstraintStream<?>> nodeCreatorMap;
27:     private final Map<ConstraintStream, TupleLifecycle<? extends AbstractTuple>> tupleLifecycleMap;
28:     private final Map<ConstraintStream, Integer> storeIndexMap;
29: 
30:     private List<AbstractNode> reversedNodeList;
