32:     public NodeBuildHelper(Set<? extends ConstraintStream> activeStreamSet, AbstractScoreInliner<Score_> scoreInliner) {
33:         this.activeStreamSet = activeStreamSet;
34:         this.scoreInliner = scoreInliner;
35:         int activeStreamSetSize = activeStreamSet.size();
36:         this.nodeCreatorMap = new HashMap<>(Math.max(16, activeStreamSetSize));
37:         this.tupleLifecycleMap = new HashMap<>(Math.max(16, activeStreamSetSize));
38:         this.storeIndexMap = new HashMap<>(Math.max(16, activeStreamSetSize / 2));
39:         this.reversedNodeList = new ArrayList<>(activeStreamSetSize);
40:     }
