54:     public void addNode(AbstractNode node, BavetAbstractConstraintStream<?> creator, BavetAbstractConstraintStream<?> parent) {
55:         reversedNodeList.add(node);
56:         nodeCreatorMap.put(node, creator);
57:         if (!(node instanceof AbstractForEachUniNode<?>)) {
58:             if (parent == null) {
59:                 throw new IllegalStateException("Impossible state: The node (" + node + ") has no parent (" + parent + ").");
60:             }
61:             putInsertUpdateRetract(parent, (TupleLifecycle<? extends AbstractTuple>) node);
62:         }
63:     }
