66:             BavetAbstractConstraintStream<?> leftParent,
67:             BavetAbstractConstraintStream<?> rightParent) {
68:         reversedNodeList.add(node);
69:         nodeCreatorMap.put(node, creator);
70:         putInsertUpdateRetract(leftParent, TupleLifecycle.ofLeft((LeftTupleLifecycle<? extends AbstractTuple>) node));
71:         putInsertUpdateRetract(rightParent, TupleLifecycle.ofRight((RightTupleLifecycle<? extends AbstractTuple>) node));
72:     }
