79:     public <Tuple_ extends AbstractTuple> void putInsertUpdateRetract(ConstraintStream stream,
80:             List<? extends AbstractConstraintStream<?>> childStreamList,
81:             Function<TupleLifecycle<Tuple_>, AbstractConditionalTupleLifecycle<Tuple_>> tupleLifecycleFunction) {
82:         TupleLifecycle<Tuple_> tupleLifecycle = getAggregatedTupleLifecycle(childStreamList);
83:         putInsertUpdateRetract(stream, tupleLifecycleFunction.apply(tupleLifecycle));
84:     }
