86:     public <Tuple_ extends AbstractTuple> TupleLifecycle<Tuple_> getAggregatedTupleLifecycle(
87:             List<? extends ConstraintStream> streamList) {
88:         TupleLifecycle<Tuple_>[] tupleLifecycles = streamList.stream()
89:                 .filter(this::isStreamActive)
90:                 .map(s -> getTupleLifecycle(s, tupleLifecycleMap))
91:                 .toArray(TupleLifecycle[]::new);
92:         switch (tupleLifecycles.length) {
93:             case 0:
94:                 throw new IllegalStateException("Impossible state: None of the streamList (" + streamList
95:                         + ") are active.");
96:             case 1:
97:                 return tupleLifecycles[0];
98:             default:
99:                 return TupleLifecycle.of(tupleLifecycles);
100:         }
101:     }
