103:     private static <Tuple_ extends AbstractTuple> TupleLifecycle<Tuple_> getTupleLifecycle(ConstraintStream stream,
104:             Map<ConstraintStream, TupleLifecycle<? extends AbstractTuple>> tupleLifecycleMap) {
105:         TupleLifecycle<Tuple_> tupleLifecycle = (TupleLifecycle<Tuple_>) tupleLifecycleMap.get(stream);
106:         if (tupleLifecycle == null) {
107:             throw new IllegalStateException("Impossible state: the stream (" + stream + ") hasn't built a node yet.");
108:         }
109:         return tupleLifecycle;
110:     }
