112:     public int reserveTupleStoreIndex(ConstraintStream tupleSourceStream) {
113:         return storeIndexMap.compute(tupleSourceStream, (k, index) -> {
114:             if (index == null) {
115:                 return 0;
116:             } else if (index < 0) {
117:                 throw new IllegalStateException("Impossible state: the tupleSourceStream (" + k
118:                         + ") is reserving a store after it has been extracted.");
119:             } else {
120:                 return index + 1;
121:             }
122:         });
123:     }
