125:     public int extractTupleStoreSize(ConstraintStream tupleSourceStream) {
126:         Integer lastIndex = storeIndexMap.put(tupleSourceStream, Integer.MIN_VALUE);
127:         return (lastIndex == null) ? 0 : lastIndex + 1;
128:     }
