130:     public List<AbstractNode> destroyAndGetNodeList() {
131:         List<AbstractNode> nodeList = this.reversedNodeList;
132:         Collections.reverse(nodeList);
133:         this.reversedNodeList = null;
134:         return nodeList;
135:     }
