141:     public AbstractNode findParentNode(BavetAbstractConstraintStream<?> childNodeCreator) {
142:         if (childNodeCreator == null) { // We've recursed to the bottom without finding a parent node.
143:             throw new IllegalStateException(
144:                     "Impossible state: node-creating stream (" + childNodeCreator + ") has no parent node.");
145:         }
146:         // Look the stream up among node creators and if found, the node is the parent node.
147:         for (Map.Entry<AbstractNode, BavetAbstractConstraintStream<?>> entry : this.nodeCreatorMap.entrySet()) {
148:             if (entry.getValue() == childNodeCreator) {
149:                 return entry.getKey();
150:             }
151:         }
152:         // Otherwise recurse to the parent node creator;
153:         // this happens for bridges, filters and other streams that do not create nodes.
154:         return findParentNode(childNodeCreator.getParent());
155:     }
